/// Installs `Node` on `global` and registers it with `registry`.
pub fn install_node<'js, T: NodeOps + EventTargetOps + 'static>(
    ctx: &rquickjs::Ctx<'js>,
    global: &rquickjs::Object<'js>,
    registry: &mut dyn InterfaceRegistry,
) -> rquickjs::Result<()> {
    let _ = ctx;
    rquickjs::Class::<NodeClass<T>>::define(global)?;
    register_node(registry);
    Ok(())
}
